  const mobile=useNarrowScreen(),menuRef=useRef(null);
  const [settingsSection,setSettingsSection]=useState('playback'),[reviewPadding,setReviewPadding]=useState({before:60,after:60});
  const [diagnosisReplayRequest,setDiagnosisReplayRequest]=useState(null);
  const diagnosisReplaySequence=useRef(0);
  const filterRequest=useRef(0);
  const [page,setPage]=useState('overview'),[navOpen,setNavOpen]=useState(false),[metadata,setMetadata]=useState(null),[status,setStatus]=useState({}),[rows,setRows]=useState([]),[streamState,setStreamState]=useState('connecting'),[logs,setLogs]=useState([]),[module,setModule]=useState('all'),[start,setStart]=useState(''),[end,setEnd]=useState(''),[signal,setSignal]=useState('activePower'),[grain,setGrain]=useState('hour'),[error,setError]=useState(''),[busy,setBusy]=useState(false),[diagnosis,setDiagnosis]=useState(null),[integrations,setIntegrations]=useState(null),[drawer,setDrawer]=useState(false),[forecast,setForecast]=useState(null),[reportData,setReportData]=useState(null),[historic,setHistoric]=useState([]),[historyMode,setHistoryMode]=useState(false),[toast,setToast]=useState('');
  useDialogFocus(menuRef,mobile&&navOpen,()=>setNavOpen(false));
