  const sessionRef=useRef(null),sequenceRef=useRef(-1);
  const acceptPayload=useCallback((payload,{replaceHistory=false}={})=>{
    const sequence=Number(payload.sequence??payload.replay?.sequence),session=payload.replay?.session_id||payload.session_id;
    if(Number.isFinite(sequence)&&sequence<sequenceRef.current)return false;
    if(Number.isFinite(sequence))sequenceRef.current=sequence;
    const changed=!!session&&session!==sessionRef.current;
    if(session)sessionRef.current=session;
    const incoming=(Array.isArray(payload.history)?payload.history.map(normalizeRow):normalizeEvent(payload));
    const received=payload.snapshot?.received_at||new Date().toISOString();
    if(changed){setLogs([]);clearVisibleNotifications();}
    if(changed||replaceHistory||incoming.length)setRows(old=>appendRows(changed||replaceHistory?[]:old,incoming.map(r=>({...r,received_at:r.received_at||received}))));
    if(payload.replay||payload.snapshot)setStatus(old=>({...old,...payload.replay,...payload.snapshot,highlight:payload.replay?.highlight??(changed?null:old.highlight),recorded_at:payload.snapshot?.timestamp||incoming.at(-1)?.recorded_at||(changed?null:old.recorded_at)}));
    if(incoming.length&&payload.type==='telemetry')setLogs(old=>[{recorded_at:incoming[0].recorded_at,received_at:received,count:incoming.length,type:'received'},...old].slice(0,60));
    if(payload.snapshot?.alarms)setDiagnosis(d=>({...d,alarms:payload.snapshot.alarms}));
    consumeNotifications(payload);
    return true;
  },[consumeNotifications,clearVisibleNotifications]);
  const refresh=useCallback(async()=>{const jobs=await Promise.allSettled([api.metadata(),api.diagnosis(),api.integrations(),api.reports()]);if(jobs[0].status==='fulfilled'){const b=jobs[0].value;setMetadata(b);acceptPayload(b,{replaceHistory:true});setIntegrations(b.integrations);setError('');}else setError(jobs[0].reason.message);[setDiagnosis,setIntegrations,setReportData].forEach((fn,i)=>{if(jobs[i+1].status==='fulfilled')fn(jobs[i+1].value)});},[acceptPayload]);
  useEffect(()=>{window.scrollTo({top:0,behavior:'auto'});},[page]);
  useEffect(()=>{refresh();return openStream(acceptPayload,state=>{if(state==='connected')sequenceRef.current=-1;setStreamState(state);});},[refresh,acceptPayload]);
  useEffect(()=>{if(Array.isArray(diagnosis?.alarms))hydrateNotifications(diagnosis.alarms);},[diagnosis?.alarms,hydrateNotifications]);
