  const availability=availabilityFor(metadata,module,grain);
  const showHistory=page==='equipment'&&equipmentMode==='history'&&historyMode;
  const displayModule=showHistory?(appliedQuery?.module||module):module;
  const displaySignal=showHistory?(appliedQuery?.signal||signal):signal;
  const displayGrain=showHistory?(appliedQuery?.grain||grain):'raw';
  const queryDirty=showHistory&&!sameQuery(appliedQuery,{module,signal,grain,start,end});
